insert into public.settings (id, data, updated_at) values (1, $json${"store":{"name":"Mây Trắng","legal":"Hộ kinh doanh Mây Trắng","hotline":"1900 6363","email":"hello@maytrang.vn","address":"Số 18 Nguyễn Văn Huyên, Cầu Giấy, Hà Nội","taxCode":"0108 452 771","announcement":"Miễn phí giao hàng toàn quốc cho hoá đơn từ 299.000đ","bank":{"bankId":"VCB","name":"Vietcombank","no":"0071 0012 3456 7","holder":"HO KINH DOANH MAY TRANG"}},"shipping":{"freeThreshold":299000,"expressFee":15000,"pickupFee":0,"fees":{"hn":22000,"hcm":22000,"north":30000,"central":35000,"south":30000},"packagingPerOrder":4000,"avgShipCost":26000},"finance":{"monthlyFixed":[{"id":"rent","name":"Mặt bằng & kho","amount":3000000},{"id":"salary","name":"Lương đội ngũ","amount":6000000},{"id":"ads","name":"Marketing cố định","amount":2000000},{"id":"tools","name":"Công cụ & phần mềm","amount":800000},{"id":"depreciation","name":"Khấu hao thiết bị","amount":500000},{"id":"other","name":"Chi phí khác","amount":800000}],"marketingRatePct":8,"tax":{"enabled":true,"threshold":200000000,"vatPct":1,"pitPct":0.5},"channelFees":{"website":1.2,"shopee":11.5,"tiktok":9.5,"facebook":2.5,"event":1.5,"wholesale":0},"targetRevenue":500000000,"initialInvestment":80000000,"discountRatePct":12,"growthY2Pct":35,"growthY3Pct":28,"fixedGrowthPct":8,"cogsInflationPct":3,"conversionRatePct":2.8,"sessionsPerMonth":9200},"storefront":{"returnDays":30,"installmentNote":"Thanh toán an toàn, thông tin thẻ không được lưu trên hệ thống."},"updatedAt":"2026-11-08T17:40:40.494Z"}$json$::jsonb, '2026-11-08T17:40:40.494Z')
insert into public.products (id, slug, name, sku, category, price, compare_at, cost, stock, sold, rating, review_count, volume, weight, badge, short_description, description, benefits, ingredients, usage_steps, skin_types, images, variants, active, created_at) values ('SP-001', 'phan-phu-kiem-dau-may-trang', 'Phấn phủ kiềm dầu Mây Trắng', 'MT-PP-001', 'makeup', 289000, 350000, 112000, 128, 1248, 4.9, 214, '8g', 60, 'Bán chạy', 'Mỏng nhẹ như mây, kiềm dầu 8 giờ, finish trong veo tự nhiên.', '<p>Phấn phủ Mây Trắng được nghiền mịn từ bột khoáng và chiết xuất trà xanh, cho lớp phủ mỏng nhẹ như mây nhưng vẫn kiểm soát dầu hiệu quả suốt 8 giờ. Hạt phấn siêu mịn giúp che phủ lỗ chân lông, làm mờ khuyết điểm nhỏ mà không gây cảm giác nặng mặt.</p><p>Công thức không cồn, không hương liệu tổng hợp, phù hợp cả với làn da nhạy cảm. Finish lì nhẹ, tự nhiên, không bết dính khi thời tiết nóng ẩm.</p>', $json$["Kiềm dầu 8 giờ, giảm bóng nhờn","Che phủ tự nhiên, không bít lỗ chân lông","Bột khoáng dịu nhẹ, an toàn cho da nhạy cảm","Thiết kế hộp gương tiện mang theo"]$json$::jsonb, 'Mica, Silica, Zinc Oxide, Trà xanh (Camellia Sinensis), Vitamin E, Bisabolol. Không paraben, không hương liệu tổng hợp.', $json$["Dùng sau bước kem lót/kem nền.","Lấy lượng vừa đủ, gõ nhẹ lên nắp để tán đều.","Phủ từ vùng chữ T ra ngoài, dặm thêm khi cần."]$json$::jsonb, $json$["Da dầu","Da hỗn hợp","Da nhạy cảm"]$json$::jsonb, $json$["assets/img/products/sp-001-a.svg","assets/img/products/sp-001-b.svg","assets/img/ingredients/tea.svg"]$json$::jsonb, $json$[{"name":"Sáng tự nhiên","sku":"MT-PP-001-01"},{"name":"Tự nhiên","sku":"MT-PP-001-02"},{"name":"Hồng đào","sku":"MT-PP-001-03"}]$json$::jsonb, true, '2026-11-08T17:40:40.533Z') on conflict (id) do nothing;
insert into public.products (id, slug, name, sku, category, price, compare_at, cost, stock, sold, rating, review_count, volume, weight, badge, short_description, description, benefits, ingredients, usage_steps, skin_types, images, variants, active, created_at) values ('SP-002', 'kem-duong-am-sen-hong', 'Kem dưỡng ẩm sen hồng', 'MT-KD-002', 'skincare', 329000, 390000, 128000, 96, 986, 4.8, 168, '50ml', 120, '', 'Cấp ẩm sâu, làm dịu da nhạy cảm với chiết xuất sen hồng Việt Nam.', '<p>Kem dưỡng ẩm sen hồng kết hợp nước sen cô đặc, rau má và ceramide thực vật giúp phục hồi hàng rào ẩm, làm dịu cảm giác căng rát do khô hạn. Kết cấu gel-cream mỏng nhẹ, thấm nhanh, không gây bí da.</p><p>Sau 2 tuần sử dụng, làn da mềm mại hơn, giảm bong tróc và giữ ẩm tự nhiên suốt 24 giờ. Phù hợp dùng sáng và tối.</p>', $json$["Cấp ẩm 24 giờ, phục hồi hàng rào da","Làm dịu da đỏ, da yếu sau treatment","Kết cấu nhẹ, không gây bí da","Chiết xuất sen hồng trồng tại Đồng Tháp"]$json$::jsonb, 'Nước sen hồng, Glycerin, Rau má, Ceramide NP, Squalane, Panthenol, Hyaluronic Acid.', $json$["Làm sạch và cân bằng da.","Lấy 2 hạt đậu kem, chấm đều 5 điểm.","Massage nhẹ theo chiều kim đồng hồ đến khi thấm."]$json$::jsonb, $json$["Da khô","Da nhạy cảm","Mọi loại da"]$json$::jsonb, $json$["assets/img/products/sp-002-a.svg","assets/img/products/sp-002-b.svg","assets/img/ingredients/lotus.svg"]$json$::jsonb, $json$[]$json$::jsonb, true, '2026-11-08T17:40:40.533Z') on conflict (id) do nothing;
insert into public.products (id, slug, name, sku, category, price, compare_at, cost, stock, sold, rating, review_count, volume, weight, badge, short_description, description, benefits, ingredients, usage_steps, skin_types, images, variants, active, created_at) values ('SP-003', 'kem-nen-duong-da-nhe', 'Kem nền dưỡng da nhẹ', 'MT-KN-003', 'makeup', 359000, null, 142000, 74, 642, 4.7, 112, '30ml', 90, 'Mới', 'Che phủ tự nhiên, dưỡng ẩm, không gây bít lỗ chân lông.', '<p>Kem nền Mây Trắng cho lớp nền mỏng nhẹ, che phủ trung bình mà vẫn giữ được độ trong tự nhiên của da. Công thức chứa niacinamide và chiết xuất trà xanh giúp làm đều màu, giảm thâm sau một thời gian dùng.</p><p>Chất kem dễ tán, không cakey, không oxy hoá. Có thể dùng tay, cọ hoặc mút ẩm mà vẫn cho finish đẹp.</p>', $json$["Che phủ trung bình, tự nhiên","Dưỡng da với niacinamide","Không gây bít lỗ chân lông","Bền màu 10 giờ"]$json$::jsonb, 'Nước tinh khiết, Titanium Dioxide, Niacinamide, Trà xanh, Glycerin, Squalane, Vitamin E.', $json$["Lắc đều trước khi dùng.","Lấy một lượng bằng hạt đậu, tán đều từ giữa mặt.","Dặm thêm lớp mỏng ở vùng cần che phủ."]$json$::jsonb, $json$["Da thường","Da hỗn hợp","Da dầu"]$json$::jsonb, $json$["assets/img/products/sp-003-a.svg","assets/img/products/sp-003-b.svg","assets/img/ingredients/tea.svg"]$json$::jsonb, $json$[{"name":"Sáng 01","sku":"MT-KN-003-01"},{"name":"Tự nhiên 02","sku":"MT-KN-003-02"},{"name":"Be ấm 03","sku":"MT-KN-003-03"}]$json$::jsonb, true, '2026-11-08T17:40:40.533Z') on conflict (id) do nothing;
insert into public.products (id, slug, name, sku, category, price, compare_at, cost, stock, sold, rating, review_count, volume, weight, badge, short_description, description, benefits, ingredients, usage_steps, skin_types, images, variants, active, created_at) values ('SP-004', 'kem-chong-nang-vo-co', 'Kem chống nắng vô cơ', 'MT-CN-004', 'suncare', 399000, 450000, 158000, 82, 721, 4.8, 156, '50ml', 120, '', 'Bảo vệ phổ rộng SPF50+ PA++++, nâng tông nhẹ, an toàn cho da nhạy cảm.', '<p>Kem chống nắng vô cơ sử dụng Zinc Oxide và Titanium Dioxide, tạo màng chắn vật lý trước tia UVA/UVB mà không gây kích ứng. Chỉ số SPF50+ PA++++ bảo vệ da trước tác động của nắng và ánh sáng xanh.</p><p>Kết cấu mỏng nhẹ, nâng tông tự nhiên, không vệt trắng. Phù hợp dùng hằng ngày, kể cả khi trang điểm.</p>', $json$["SPF50+ PA++++ phổ rộng","Nâng tông nhẹ, không bết dính","Không thấm vào da, an toàn cho da nhạy cảm","Kháng nước nhẹ, phù hợp khí hậu nóng ẩm"]$json$::jsonb, 'Zinc Oxide 18%, Titanium Dioxide 6%, Squalane, Trà xanh, Vitamin E, Glycerin.', $json$["Dùng sau bước dưỡng ẩm, trước trang điểm.","Thoa lượng đủ 2 đốt ngón tay cho toàn mặt và cổ.","Thoa lại mỗi 2-3 giờ khi ở ngoài trời."]$json$::jsonb, $json$["Da nhạy cảm","Da dầu","Mọi loại da"]$json$::jsonb, $json$["assets/img/products/sp-004-a.svg","assets/img/products/sp-004-b.svg","assets/img/ingredients/centella.svg"]$json$::jsonb, $json$[]$json$::jsonb, true, '2026-11-08T17:40:40.533Z') on conflict (id) do nothing;
insert into public.products (id, slug, name, sku, category, price, compare_at, cost, stock, sold, rating, review_count, volume, weight, badge, short_description, description, benefits, ingredients, usage_steps, skin_types, images, variants, active, created_at) values ('SP-005', 'sua-rua-mat-rau-ma', 'Sữa rửa mặt dịu nhẹ rau má', 'MT-SRM-005', 'skincare', 219000, null, 76000, 180, 1420, 4.7, 240, '120ml', 150, 'Bán chạy', 'Làm sạch sâu mà không khô căng, chiết xuất rau má làm dịu da.', '<p>Sữa rửa mặt gốc amino acid nhẹ nhàng loại bỏ bụi bẩn, dầu thừa và kem chống nắng mà vẫn giữ được độ ẩm tự nhiên. Rau má và trà xanh giúp làm dịu các vùng da mẩn đỏ, giảm mụn ẩn.</p><p>Bọt mịn, không xà phòng, độ pH 5.5 cân bằng với da. Dùng được cho cả da dầu mụn và da nhạy cảm.</p>', $json$["Làm sạch sâu, không khô căng","pH 5.5 cân bằng","Rau má làm dịu, giảm mẩn đỏ","Phù hợp da dầu mụn"]$json$::jsonb, 'Nước rau má, Sodium Cocoyl Isethionate, Glycerin, Trà xanh, Panthenol, Allantoin.', $json$["Làm ướt mặt, lấy lượng vừa đủ tạo bọt.","Massage 30-60 giây, tránh vùng mắt.","Rửa lại với nước ấm và lau khô."]$json$::jsonb, $json$["Da dầu","Da mụn","Da nhạy cảm"]$json$::jsonb, $json$["assets/img/products/sp-005-a.svg","assets/img/products/sp-005-b.svg","assets/img/ingredients/centella.svg"]$json$::jsonb, $json$[]$json$::jsonb, true, '2026-11-08T17:40:40.533Z') on conflict (id) do nothing;
insert into public.products (id, slug, name, sku, category, price, compare_at, cost, stock, sold, rating, review_count, volume, weight, badge, short_description, description, benefits, ingredients, usage_steps, skin_types, images, variants, active, created_at) values ('SP-006', 'tay-trang-nuoc-hoa-hong', 'Tẩy trang nước hoa hồng', 'MT-TT-006', 'skincare', 249000, null, 88000, 110, 640, 4.6, 96, '150ml', 180, '', 'Tan lớp trang điểm và kem chống nắng chỉ trong một lần lau.', '<p>Nước tẩy trang micellar với nước hoa hồng và micelle dịu nhẹ giúp loại bỏ hoàn toàn lớp trang điểm, kem chống nắng và dầu thừa mà không cần chà xát mạnh. Da sạch thoáng, mềm mại, không nhờn dính.</p><p>Không cồn, không hương liệu tổng hợp, an toàn cho vùng da quanh mắt.</p>', $json$["Sạch makeup và chống nắng chỉ 1 lần","Không cồn, không gây khô","Nước hoa hồng làm dịu da","Dùng được cho vùng mắt"]$json$::jsonb, 'Nước hoa hồng, Poloxamer 184, Glycerin, Panthenol, Sodium Hyaluronate.', $json$["Thấm đủ ướt bông tẩy trang.","Giữ trên da 5-10 giây rồi lau nhẹ.","Rửa lại bằng sữa rửa mặt."]$json$::jsonb, $json$["Mọi loại da","Da nhạy cảm"]$json$::jsonb, $json$["assets/img/products/sp-006-a.svg","assets/img/products/sp-006-b.svg","assets/img/ingredients/lotus.svg"]$json$::jsonb, $json$[]$json$::jsonb, true, '2026-11-08T17:40:40.533Z') on conflict (id) do nothing;
insert into public.products (id, slug, name, sku, category, price, compare_at, cost, stock, sold, rating, review_count, volume, weight, badge, short_description, description, benefits, ingredients, usage_steps, skin_types, images, variants, active, created_at) values ('SP-007', 'serum-vitamin-c-tra-xanh', 'Serum vitamin C trà xanh', 'MT-SR-007', 'skincare', 459000, 520000, 176000, 58, 423, 4.8, 88, '30ml', 70, 'Mới', 'Làm sáng da, mờ thâm và chống oxy hoá với 12% vitamin C.', '<p>Serum vitamin C nồng độ 12% kết hợp trà xanh và vitamin E giúp làm sáng da, mờ thâm nám và bảo vệ da trước gốc tự do. Công thức ổn định, không gây châm chích.</p><p>Dùng đều đặn mỗi sáng, làn da trở nên đều màu và rạng rỡ hơn sau 4 tuần.</p>', $json$["12% vitamin C làm sáng, mờ thâm","Chống oxy hoá với trà xanh","Kết cấu lỏng, thấm nhanh","Không cồn, không gây kích ứng"]$json$::jsonb, 'Ascorbic Acid 12%, Trà xanh, Vitamin E, Ferulic Acid, Glycerin, Hyaluronic Acid.', $json$["Dùng sau toner, trước kem dưỡng.","Lấy 3-4 giọt, vỗ đều lên mặt.","Buổi sáng cần dùng kèm kem chống nắng."]$json$::jsonb, $json$["Da thường","Da xỉn màu","Da dầu"]$json$::jsonb, $json$["assets/img/products/sp-007-a.svg","assets/img/products/sp-007-b.svg","assets/img/ingredients/tea.svg"]$json$::jsonb, $json$[]$json$::jsonb, true, '2026-11-08T17:40:40.533Z') on conflict (id) do nothing;
insert into public.products (id, slug, name, sku, category, price, compare_at, cost, stock, sold, rating, review_count, volume, weight, badge, short_description, description, benefits, ingredients, usage_steps, skin_types, images, variants, active, created_at) values ('SP-008', 'mat-na-dat-set-tra-xanh', 'Mặt nạ đất sét trà xanh', 'MT-MN-008', 'skincare', 189000, null, 62000, 140, 890, 4.5, 132, '100g', 140, '', 'Hút dầu thừa, se khít lỗ chân lông, làm dịu da mụn.', '<p>Mặt nạ đất sét trà xanh kết hợp kaolin và bentonite giúp hút sạch dầu thừa, bụi bẩn trong lỗ chân lông. Trà xanh và rau má làm dịu vùng da mụn, giảm sưng đỏ.</p><p>Kết cấu mịn, dễ rửa, không làm khô căng da sau khi dùng.</p>', $json$["Hút dầu, se khít lỗ chân lông","Giảm mụn và mẩn đỏ","Không gây khô căng","Dùng 2 lần/tuần"]$json$::jsonb, 'Kaolin, Bentonite, Trà xanh, Rau má, Glycerin, Zinc PCA.', $json$["Rửa mặt sạch và lau khô.","Thoa lớp mỏng, tránh vùng mắt và môi.","Để 10-12 phút rồi rửa sạch với nước ấm."]$json$::jsonb, $json$["Da dầu","Da mụn","Da hỗn hợp"]$json$::jsonb, $json$["assets/img/products/sp-008-a.svg","assets/img/products/sp-008-b.svg","assets/img/ingredients/tea.svg"]$json$::jsonb, $json$[]$json$::jsonb, true, '2026-11-08T17:40:40.533Z') on conflict (id) do nothing;
insert into public.products (id, slug, name, sku, category, price, compare_at, cost, stock, sold, rating, review_count, volume, weight, badge, short_description, description, benefits, ingredients, usage_steps, skin_types, images, variants, active, created_at) values ('SP-009', 'xit-khoang-hoa-sen', 'Xịt khoáng hoa sen', 'MT-XK-009', 'skincare', 169000, null, 52000, 220, 1130, 4.6, 118, '100ml', 130, '', 'Cấp ẩm tức thì, làm dịu da, dùng được cả khi đang trang điểm.', '<p>Xịt khoáng hoa sen với nước sen cất và khoáng vi lượng giúp cấp ẩm tức thì, làm dịu da khô và mẩn đỏ. Hạt xịt mịn, không làm trôi lớp trang điểm.</p><p>Mang theo bên mình để làm mới làn da bất cứ lúc nào trong ngày.</p>', $json$["Cấp ẩm tức thì","Làm dịu da nóng, mẩn đỏ","Không làm trôi trang điểm","Hương sen tự nhiên nhẹ"]$json$::jsonb, 'Nước hoa sen, Nước khoáng, Glycerin, Panthenol, Sodium PCA.', $json$["Giữ cách mặt 20cm và xịt đều.","Vỗ nhẹ để thấm.","Dùng trước hoặc sau trang điểm khi cần."]$json$::jsonb, $json$["Mọi loại da","Da khô","Da nhạy cảm"]$json$::jsonb, $json$["assets/img/products/sp-009-a.svg","assets/img/products/sp-009-b.svg","assets/img/ingredients/lotus.svg"]$json$::jsonb, $json$[]$json$::jsonb, true, '2026-11-08T17:40:40.533Z') on conflict (id) do nothing;
insert into public.products (id, slug, name, sku, category, price, compare_at, cost, stock, sold, rating, review_count, volume, weight, badge, short_description, description, benefits, ingredients, usage_steps, skin_types, images, variants, active, created_at) values ('SP-010', 'son-duong-dau-dua', 'Son dưỡng dầu dừa', 'MT-SD-010', 'makeup', 129000, null, 38000, 260, 2050, 4.7, 302, '4g', 30, 'Yêu thích', 'Dưỡng môi mềm mịn với dầu dừa Bến Tre, màu tự nhiên.', '<p>Son dưỡng dầu dừa Bến Tre kết hợp bơ hạt mỡ và vitamin E giúp dưỡng môi mềm, giảm nứt nẻ, đặc biệt trong mùa hanh khô. Lớp finish bóng nhẹ, màu tự nhiên.</p><p>An toàn khi nuốt phải một lượng nhỏ, phù hợp dùng hằng ngày.</p>', $json$["Dưỡng ẩm môi suốt 6 giờ","Giảm nứt nẻ, mềm môi","Dầu dừa nguyên chất Bến Tre","Có thể dùng làm lớp lót son"]$json$::jsonb, 'Dầu dừa Bến Tre, Bơ hạt mỡ, Sáp ong, Vitamin E, Dầu jojoba.', $json$["Thoa trực tiếp lên môi.","Dùng nhiều lần trong ngày khi môi khô.","Dùng làm lót trước khi đánh son màu."]$json$::jsonb, $json$["Mọi loại da"]$json$::jsonb, $json$["assets/img/products/sp-010-a.svg","assets/img/products/sp-010-b.svg","assets/img/ingredients/coconut.svg"]$json$::jsonb, $json$[{"name":"Không màu","sku":"MT-SD-010-01"},{"name":"Hồng nhạt","sku":"MT-SD-010-02"}]$json$::jsonb, true, '2026-11-08T17:40:40.533Z') on conflict (id) do nothing;
insert into public.products (id, slug, name, sku, category, price, compare_at, cost, stock, sold, rating, review_count, volume, weight, badge, short_description, description, benefits, ingredients, usage_steps, skin_types, images, variants, active, created_at) values ('SP-011', 'combo-cham-soc-toan-dien', 'Combo Chăm sóc toàn diện', 'MT-CB-011', 'combo', 749000, 927000, 318000, 45, 512, 4.9, 76, '4 sản phẩm', 520, 'Tiết kiệm 20%', 'Sữa rửa mặt + Tẩy trang + Kem dưỡng + Chống nắng — trọn chu trình mỗi ngày.', '<p>Combo Chăm sóc toàn diện gồm 4 sản phẩm thiết yếu cho chu trình chăm da tối giản: Sữa rửa mặt rau má 120ml, Tẩy trang hoa hồng 150ml, Kem dưỡng sen hồng 50ml và Kem chống nắng vô cơ 50ml.</p><p>Tiết kiệm 178.000đ so với mua lẻ, đóng gói trong hộp quà tặng kèm thiệp viết tay.</p>', $json$["Tiết kiệm 178.000đ","Đủ 4 bước chăm da cơ bản","Hộp quà tặng kèm thiệp","Phù hợp làm quà tặng"]$json$::jsonb, 'Xem chi tiết từng sản phẩm trong bộ.', $json$["Sáng: Rửa mặt → Kem dưỡng → Chống nắng.","Tối: Tẩy trang → Rửa mặt → Kem dưỡng."]$json$::jsonb, $json$["Mọi loại da"]$json$::jsonb, $json$["assets/img/products/sp-011-a.svg","assets/img/products/sp-011-b.svg","assets/img/ingredients/centella.svg"]$json$::jsonb, $json$[]$json$::jsonb, true, '2026-11-08T17:40:40.533Z') on conflict (id) do nothing;
insert into public.products (id, slug, name, sku, category, price, compare_at, cost, stock, sold, rating, review_count, volume, weight, badge, short_description, description, benefits, ingredients, usage_steps, skin_types, images, variants, active, created_at) values ('SP-012', 'combo-tan-khach-hang', 'Combo Tân khách hàng', 'MT-CB-012', 'combo', 399000, 548000, 166000, 60, 738, 4.8, 104, '3 sản phẩm', 380, 'Best seller', 'Bộ trải nghiệm 3 món: rửa mặt, dưỡng ẩm và chống nắng mini.', '<p>Combo dành cho người mới bắt đầu: Sữa rửa mặt rau má 50ml, Kem dưỡng sen hồng 15ml và Kem chống nắng 15ml, đựng trong túi vải Mây Trắng.</p><p>Kích thước nhỏ gọn, phù hợp mang theo du lịch hoặc làm quà tặng thử sản phẩm.</p>', $json$["Trải nghiệm 3 sản phẩm best seller","Kích thước mini tiện lợi","Túi vải Mây Trắng kèm theo","Tiết kiệm 149.000đ"]$json$::jsonb, 'Xem chi tiết từng sản phẩm trong bộ.', $json$["Dùng theo hướng dẫn trên từng sản phẩm."]$json$::jsonb, $json$["Mọi loại da"]$json$::jsonb, $json$["assets/img/products/sp-012-a.svg","assets/img/products/sp-012-b.svg","assets/img/ingredients/coconut.svg"]$json$::jsonb, $json$[]$json$::jsonb, true, '2026-11-08T17:40:40.533Z') on conflict (id) do nothing;
insert into public.products (id, slug, name, sku, category, price, compare_at, cost, stock, sold, rating, review_count, volume, weight, badge, short_description, description, benefits, ingredients, usage_steps, skin_types, images, variants, active, created_at) values ('SP-013', 'bo-mini-trai-nghiem', 'Bộ mini trải nghiệm', 'MT-CB-013', 'combo', 259000, 337000, 96000, 90, 380, 4.6, 62, '4 sản phẩm mini', 260, '', '4 món mini gọn nhẹ cho chuyến đi, đủ bước làm sạch và dưỡng da.', '<p>Bộ mini gồm sữa rửa mặt, tẩy trang, kem dưỡng và son dưỡng dạng mini, đóng gói trong túi zip chống nước. Giải pháp chăm da gọn nhẹ khi đi du lịch hoặc công tác.</p>', $json$["4 món mini tiện lợi","Túi zip chống nước","Đủ bước làm sạch và dưỡng","Tiết kiệm 78.000đ"]$json$::jsonb, 'Xem chi tiết từng sản phẩm trong bộ.', $json$["Dùng theo hướng dẫn trên từng sản phẩm."]$json$::jsonb, $json$["Mọi loại da"]$json$::jsonb, $json$["assets/img/products/sp-013-a.svg","assets/img/products/sp-013-b.svg","assets/img/ingredients/lotus.svg"]$json$::jsonb, $json$[]$json$::jsonb, true, '2026-11-08T17:40:40.533Z') on conflict (id) do nothing;
insert into public.products (id, slug, name, sku, category, price, compare_at, cost, stock, sold, rating, review_count, volume, weight, badge, short_description, description, benefits, ingredients, usage_steps, skin_types, images, variants, active, created_at) values ('SP-014', 'bo-duong-the-dua-ben-tre', 'Bơ dưỡng thể dừa Bến Tre', 'MT-BT-014', 'body', 279000, 320000, 104000, 70, 290, 4.7, 54, '200ml', 260, '', 'Dưỡng thể mềm mịn với dầu dừa và bơ hạt mỡ, hương dừa nhẹ.', '<p>Bơ dưỡng thể dừa Bến Tre kết hợp dầu dừa nguyên chất, bơ hạt mỡ và vitamin E giúp dưỡng ẩm sâu, làm mềm vùng da khô như khuỷu tay, đầu gối. Thấm nhanh, không bết dính.</p><p>Hương dừa tự nhiên dịu nhẹ, mang lại cảm giác thư giãn sau mỗi lần tắm.</p>', $json$["Dưỡng ẩm sâu 24 giờ","Làm mềm da khô, sần","Thấm nhanh, không bết dính","Hương dừa tự nhiên"]$json$::jsonb, 'Dầu dừa Bến Tre, Bơ hạt mỡ, Glycerin, Vitamin E, Sáp ong.', $json$["Dùng sau khi tắm, khi da còn ẩm.","Massage đều toàn thân, tập trung vùng khô.","Dùng 1-2 lần mỗi ngày."]$json$::jsonb, $json$["Da khô","Mọi loại da"]$json$::jsonb, $json$["assets/img/products/sp-014-a.svg","assets/img/products/sp-014-b.svg","assets/img/ingredients/coconut.svg"]$json$::jsonb, $json$[]$json$::jsonb, true, '2026-11-08T17:40:40.533Z') on conflict (id) do nothing;
