insert into public.reviews (id, product_id, name, rating, text, verified, source, created_at) values ('RV-001', 'SP-001', 'Ngọc Anh', 5, 'Da mình dầu nặng mà dùng phấn này đến chiều vẫn khô thoáng. Hạt phấn rất mịn, không bị cakey.', true, 'seed', '2026-11-02T17:40:40.494Z') on conflict (id) do nothing;
insert into public.reviews (id, product_id, name, rating, text, verified, source, created_at) values ('RV-002', 'SP-001', 'Lan Phương', 5, 'Màu tự nhiên, hợp da trung bình. Đóng gói xinh, có gương tiện mang theo.', true, 'seed', '2026-10-25T17:40:40.494Z') on conflict (id) do nothing;
insert into public.reviews (id, product_id, name, rating, text, verified, source, created_at) values ('RV-003', 'SP-001', 'Hồng Nhung', 4, 'Che phủ ổn với khuyết điểm nhỏ. Mùa hè cần dặm lại sau 5-6 tiếng.', true, 'seed', '2026-10-17T17:40:40.494Z') on conflict (id) do nothing;
insert into public.reviews (id, product_id, name, rating, text, verified, source, created_at) values ('RV-004', 'SP-002', 'Thu Hà', 5, 'Kem thấm nhanh, không bết. Da mình bị đỏ sau treatment dùng rất dịu, hết căng rát.', true, 'seed', '2026-11-05T17:40:40.494Z') on conflict (id) do nothing;
insert into public.reviews (id, product_id, name, rating, text, verified, source, created_at) values ('RV-005', 'SP-002', 'Mai Chi', 4, 'Mùi sen nhẹ dễ chịu. Hơi lỏng so với kem dưỡng mình từng dùng nhưng thấm tốt.', true, 'seed', '2026-10-21T17:40:40.494Z') on conflict (id) do nothing;
insert into public.reviews (id, product_id, name, rating, text, verified, source, created_at) values ('RV-006', 'SP-003', 'Minh Trang', 5, 'Lớp nền mỏng tự nhiên, không bị oxy hoá. Dùng kèm phấn phủ là đủ cho cả ngày.', true, 'seed', '2026-10-31T17:40:40.494Z') on conflict (id) do nothing;
insert into public.reviews (id, product_id, name, rating, text, verified, source, created_at) values ('RV-007', 'SP-004', 'Bảo Ngọc', 5, 'Chống nắng vô cơ mà không bị vệt trắng, nâng tông rất nhẹ. Da nhạy cảm dùng ổn.', true, 'seed', '2026-10-28T17:40:40.494Z') on conflict (id) do nothing;
insert into public.reviews (id, product_id, name, rating, text, verified, source, created_at) values ('RV-008', 'SP-005', 'Kim Ngân', 5, 'Rửa xong không khô, bọt mịn. Mụn ẩn giảm rõ sau 2 tuần.', true, 'seed', '2026-11-06T17:40:40.494Z') on conflict (id) do nothing;
insert into public.reviews (id, product_id, name, rating, text, verified, source, created_at) values ('RV-009', 'SP-005', 'Phương Thảo', 4, 'Dịu nhẹ, hợp da dầu. Tuýp hơi nhỏ so với giá nhưng chất lượng tốt.', true, 'seed', '2026-10-14T17:40:40.494Z') on conflict (id) do nothing;
insert into public.reviews (id, product_id, name, rating, text, verified, source, created_at) values ('RV-010', 'SP-007', 'Hà My', 5, 'Serum thấm nhanh, không dính. Sau 3 tuần da sáng hơn rõ, thâm mờ dần.', true, 'seed', '2026-10-30T17:40:40.494Z') on conflict (id) do nothing;
insert into public.reviews (id, product_id, name, rating, text, verified, source, created_at) values ('RV-011', 'SP-008', 'Quỳnh Anh', 4, 'Mặt nạ hút dầu tốt, rửa dễ. Hơi khô nhẹ nên mình chỉ dùng vùng chữ T.', true, 'seed', '2026-10-23T17:40:40.494Z') on conflict (id) do nothing;
insert into public.reviews (id, product_id, name, rating, text, verified, source, created_at) values ('RV-012', 'SP-010', 'Trà My', 5, 'Son dưỡng mềm môi, mùi dừa thơm nhẹ. Mình dùng làm lót son rất hợp.', true, 'seed', '2026-11-03T17:40:40.494Z') on conflict (id) do nothing;
insert into public.reviews (id, product_id, name, rating, text, verified, source, created_at) values ('RV-013', 'SP-011', 'Diệu Linh', 5, 'Combo đóng hộp quà rất đẹp, mình mua tặng mẹ. Đủ 4 bước, tiết kiệm hơn mua lẻ.', true, 'seed', '2026-11-01T17:40:40.494Z') on conflict (id) do nothing;
insert into public.reviews (id, product_id, name, rating, text, verified, source, created_at) values ('RV-014', 'SP-012', 'Hoàng Yến', 5, 'Bộ mini xinh, đủ dùng thử 2 tuần. Túi vải đựng rất tiện mang đi du lịch.', true, 'seed', '2026-10-26T17:40:40.494Z') on conflict (id) do nothing;
insert into public.reviews (id, product_id, name, rating, text, verified, source, created_at) values ('RV-015', 'SP-006', 'Thanh Huyền', 5, 'Tẩy trang sạch cả mascara chống nước, không cay mắt. Rất đáng tiền.', true, 'seed', '2026-11-04T17:40:40.494Z') on conflict (id) do nothing;
insert into public.reviews (id, product_id, name, rating, text, verified, source, created_at) values ('RV-016', 'SP-009', 'Vy', 4, 'Xịt mịn, không làm trôi makeup. Mùi sen nhẹ, mùa hè dùng rất mát.', true, 'seed', '2026-10-19T17:40:40.494Z') on conflict (id) do nothing;
